 internal SystemMonitorItemContent(CanvasItem item,ISystemMetricsService service){this.item=item;this.service=service;if(item.Height<320){item.Width=Math.Max(320,item.Width);item.Height=390;}var header=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,0,0,12)};header.Children.Add(brandMark);header.Children.Add(heading);rows.Children.Add(header);rows.Children.Add(cpu.View);rows.Children.Add(ram.View);rows.Children.Add(gpu.View);rows.Children.Add(new Border{Height=1,Margin=new Thickness(0,8,0,8)});rows.Children.Add(down.View);rows.Children.Add(up.View);rows.Width=double.NaN;rows.UseLayoutRounding=true;rows.SnapsToDevicePixels=true;TextOptions.SetTextFormattingMode(rows,TextFormattingMode.Display);TextOptions.SetTextRenderingMode(rows,TextRenderingMode.ClearType);root=WidgetTheme.Card(item,rows);root.UseLayoutRounding=true;root.SnapsToDevicePixels=true;Update(service.Snapshot);}
