 private sealed class MetricRow{private readonly WpfPath icon;private readonly TextBlock label,aux=new(){FontSize=12,VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis};private readonly Ellipse track=new(){Width=60,Height=60,StrokeThickness=5};private readonly WpfPath arc=new(){StrokeThickness=5,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round};private readonly TextBlock value=new(){FontSize=14,FontWeight=FontWeights.SemiBold,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};private readonly ArcProgressHost progress;internal Grid View{get;}internal MetricRow(string name,string geometry){icon=new WpfPath{Data=Geometry.Parse(geometry),Width=20,Height=20,Stretch=Stretch.Uniform,VerticalAlignment=VerticalAlignment.Center};label=new TextBlock{Text=name,FontSize=14,Margin=new Thickness(14,0,8,0),VerticalAlignment=VerticalAlignment.Center};progress=new ArcProgressHost(v=>arc.Data=Arc(v));var dial=new Grid{Width=60,Height=60};dial.Children.Add(track);dial.Children.Add(arc);dial.Children.Add(value);View=new Grid{Height=68};View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(22)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(66)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(62)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});View.Children.Add(icon);Grid.SetColumn(label,1);View.Children.Add(label);Grid.SetColumn(dial,2);View.Children.Add(dial);Grid.SetColumn(aux,3);View.Children.Add(aux);}internal void Update(MetricValue metric,string text,WpfColor color,WidgetPalette palette,bool animate){icon.Stroke=new SolidColorBrush(color);label.Foreground=aux.Foreground=new SolidColorBrush(palette.Muted);value.Foreground=new SolidColorBrush(palette.Foreground);value.Text=metric.Availability==MetricAvailability.Available?$"{metric.Value:0}%":metric.Availability==MetricAvailability.Loading?"…":"--";aux.Text=text;track.Stroke=new SolidColorBrush(WpfColor.FromArgb(48,palette.Foreground.R,palette.Foreground.G,palette.Foreground.B));arc.Stroke=metric.Availability==MetricAvailability.Available?new SolidColorBrush(color):new SolidColorBrush(WpfColor.FromRgb(115,115,124));if(metric.Availability!=MetricAvailability.Available){progress.Clear();return;}progress.Retarget(SystemMetricRingMath.Clamp(metric.Value??0),animate);}internal void Stop()=>progress.ClearAnimation();internal void Dispose()=>progress.Dispose();private static Geometry Arc(double value){var v=SystemMetricRingMath.Clamp(value);if(v<=0)return Geometry.Empty;var radians=Math.Min(359.99,v*3.6)*Math.PI/180;const double radius=27.5;var end=new Point(30+radius*Math.Sin(radians),30-radius*Math.Cos(radians));return new PathGeometry([new PathFigure{StartPoint=new Point(30,30-radius),Segments={new ArcSegment{Point=end,Size=new Size(radius,radius),IsLargeArc=radians>Math.PI,SweepDirection=SweepDirection.Clockwise}}}]);}}
 private sealed class ArcProgressHost:Animatable{private readonly Action<double> changed;internal ArcProgressHost(Action<double> changed){this.changed=changed;}internal static readonly DependencyProperty ValueProperty=DependencyProperty.Register(nameof(Value),typeof(double),typeof(ArcProgressHost),new PropertyMetadata(0d,Changed));internal double Value{get=>(double)GetValue(ValueProperty);set=>SetValue(ValueProperty,value);}private static void Changed(DependencyObject d,DependencyPropertyChangedEventArgs e)=>((ArcProgressHost)d).changed(SystemMetricRingMath.Clamp((double)e.NewValue));internal void Retarget(double target,bool animate){target=SystemMetricRingMath.Clamp(target);var from=Value;BeginAnimation(ValueProperty,null);Value=target;if(!animate||Math.Abs(from-target)<.01)return;BeginAnimation(ValueProperty,new DoubleAnimation(from,target,TimeSpan.FromMilliseconds(700)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut},FillBehavior=FillBehavior.Stop});}internal void Clear(){BeginAnimation(ValueProperty,null);Value=0;}internal void ClearAnimation()=>BeginAnimation(ValueProperty,null);internal void Dispose(){BeginAnimation(ValueProperty,null);changed(0);}protected override Freezable CreateInstanceCore()=>new ArcProgressHost(changed);}
 private sealed class NetworkRow{private readonly Border circle;private readonly TextBlock label;private readonly WpfPath arrow;private readonly TextBlock text=new(){FontSize=12,VerticalAlignment=VerticalAlignment.Center};private readonly WpfPath spark=new(){StrokeThickness=1.6,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round};private readonly NetworkHistory history=new(30);internal Grid View{get;}internal NetworkRow(string name,bool rising){arrow=new WpfPath{Data=Geometry.Parse(rising?"M10,2 L18,10 L14,10 L14,18 L6,18 L6,10 L2,10 Z":"M10,18 L2,10 L6,10 L6,2 L14,2 L14,10 L18,10 Z"),Stretch=Stretch.Uniform};circle=new Border{Width=32,Height=32,CornerRadius=new CornerRadius(16),BorderThickness=new Thickness(2),Child=arrow,Padding=new Thickness(7)};label=new TextBlock{Text=name,FontSize=12,Margin=new Thickness(14,0,0,0),VerticalAlignment=VerticalAlignment.Center};View=new Grid{Height=40,UseLayoutRounding=true,SnapsToDevicePixels=true};View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(36)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(64)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});View.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(82)});View.Children.Add(circle);Grid.SetColumn(label,1);View.Children.Add(label);Grid.SetColumn(spark,2);View.Children.Add(spark);Grid.SetColumn(text,3);View.Children.Add(text);}internal void Update(MetricValue metric,WpfColor color,WidgetPalette palette){var brush=new SolidColorBrush(color);circle.BorderBrush=brush;arrow.Fill=brush;spark.Stroke=brush;label.Foreground=text.Foreground=new SolidColorBrush(palette.Muted);history.Add(metric.Value??0);Paint(history.Normalized());text.Text=metric.Text;}internal void Dispose(){spark.Data=Geometry.Empty;}private void Paint(IReadOnlyList<double> values){var points=NetworkGraphMath.Points(values);if(points.Count==0){spark.Data=Geometry.Empty;return;}var figure=new PathFigu